CREATE DATABASE IF NOT EXISTS `kyc_db` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci */ /*!80016 DEFAULT ENCRYPTION='N' */;
USE `kyc_db`;

CREATE TABLE IF NOT EXISTS `audit_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `case_id` varchar(255) DEFAULT NULL,
  `duration_ms` bigint DEFAULT NULL,
  `sequence_order` int DEFAULT NULL,
  `step` varchar(255) DEFAULT NULL,
  `step_details` text,
  `step_status` varchar(255) DEFAULT NULL,
  `timestamp` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=670 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


CREATE TABLE IF NOT EXISTS `fraud_result` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `case_id` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `final_name` varchar(255) DEFAULT NULL,
  `fraud_score` int DEFAULT NULL,
  `fraud_signals` varchar(255) DEFAULT NULL,
  `identity_score` int DEFAULT NULL,
  `kyc_status` varchar(255) DEFAULT NULL,
  `message` varchar(255) DEFAULT NULL,
  `risk_score` double DEFAULT NULL,
  `face_match_score_aadhaar` float DEFAULT NULL,
  `face_match_score_pan` float DEFAULT NULL,
  `face_match_status` varchar(255) DEFAULT NULL,
  `liveness_score` float DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


CREATE TABLE IF NOT EXISTS `kyc_case` (
  `case_id` varchar(255) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `current_pipeline_phase` varchar(255) DEFAULT NULL,
  `processing_end_time` datetime(6) DEFAULT NULL,
  `processing_start_time` datetime(6) DEFAULT NULL,
  `risk_score` int DEFAULT NULL,
  `status` varchar(255) DEFAULT NULL,
  `total_processing_time_ms` bigint DEFAULT NULL,
  PRIMARY KEY (`case_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


CREATE TABLE IF NOT EXISTS `kyc_data` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `aadhaar_dob` varchar(255) DEFAULT NULL,
  `aadhaar_name` varchar(255) DEFAULT NULL,
  `aadhaar_number` varchar(255) DEFAULT NULL,
  `account_number` varchar(255) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `case_id` varchar(255) DEFAULT NULL,
  `confidence_score` double DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `document_type` varchar(255) DEFAULT NULL,
  `extraction_timestamp` datetime(6) DEFAULT NULL,
  `ifsc_code` varchar(255) DEFAULT NULL,
  `kyc_result_json` json DEFAULT NULL,
  `ocr_response_json` json DEFAULT NULL,
  `pan_dob` varchar(255) DEFAULT NULL,
  `pan_father_name` varchar(255) DEFAULT NULL,
  `pan_name` varchar(255) DEFAULT NULL,
  `pan_number` varchar(255) DEFAULT NULL,
  `statement_name` varchar(255) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


